CREATE OR REPLACE FUNCTION private.barred_why(p_world uuid, p_uid uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_until timestamptz;
begin
